package com.rpb.reservation.workforce;
import com.rpb.reservation.workforce.api.WorkforceDocumentExpiryController;import com.rpb.reservation.workforce.documents.expiry.*;import com.rpb.reservation.walkin.api.*;import com.rpb.reservation.workforce.domain.WorkforceException;
import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class WorkforceDocumentExpiryApiTest {
 CurrentActorProvider actors=mock(CurrentActorProvider.class);DocumentExpiryService service=mock(DocumentExpiryService.class);UUID store=UUID.randomUUID();String path="/api/v1/stores/"+store+"/workforce/document-expiries";MockMvc mvc=MockMvcBuilders.standaloneSetup(new WorkforceDocumentExpiryController(actors,service)).setMessageConverters(new org.springframework.http.converter.json.MappingJackson2HttpMessageConverter(new com.fasterxml.jackson.databind.ObjectMapper().findAndRegisterModules().disable(com.fasterxml.jackson.databind.SerializationFeature.WRITE_DATES_AS_TIMESTAMPS))).build();
 void login(){when(actors.currentActor()).thenReturn(Optional.of(new CurrentActor(UUID.randomUUID(),UUID.randomUUID(),"staff",Set.of(),Set.of(),Set.of(store))));}
 @Test void unauthenticatedListIsPrivateAndNeverReadsDocuments()throws Exception{mvc.perform(get(path)).andExpect(status().isUnauthorized()).andExpect(header().string("Cache-Control","private, no-store"));verifyNoInteractions(service);}
 @Test void typedDefaultsAndDeniedScopeUsePrivateStatusResponses()throws Exception{login();when(service.list(any(),eq(store),eq(30),eq("all"),eq(50),eq(0))).thenReturn(new DocumentExpiryDtos.Page(store,"Asia/Singapore",LocalDate.of(2026,10,29),30,"all",0,0,0,50,0,List.of()));mvc.perform(get(path)).andExpect(status().isOk()).andExpect(header().string("Cache-Control","private, no-store")).andExpect(jsonPath("$.today").value("2026-10-29")).andExpect(jsonPath("$.total").value(0));mvc.perform(get(path+"?days=invalid")).andExpect(status().isBadRequest());doThrow(WorkforceException.invalid()).when(service).list(any(),any(),eq(0),any(),anyInt(),anyInt());mvc.perform(get(path+"?days=0")).andExpect(status().isBadRequest());doThrow(WorkforceException.forbidden()).when(service).list(any(),any(),eq(7),any(),anyInt(),anyInt());mvc.perform(get(path+"?days=7")).andExpect(status().isForbidden()).andExpect(header().string("Cache-Control","private, no-store"));}
 @Test void batchAndEmployeeFilterArePrivateTypedAndDoNotReturnCertificateSecrets()throws Exception{UUID employee=UUID.randomUUID();mvc.perform(get(path+"/employees?employeeIds="+employee)).andExpect(status().isUnauthorized()).andExpect(header().string("Cache-Control","private, no-store"));login();when(service.employeeCounts(any(),eq(store),eq(30),eq(List.of(employee)))).thenReturn(new DocumentExpiryDtos.EmployeePage(store,"Asia/Singapore",LocalDate.of(2026,10,29),30,List.of(new DocumentExpiryDtos.EmployeeCount(employee,2,1))));mvc.perform(get(path+"/employees?employeeIds="+employee)).andExpect(status().isOk()).andExpect(jsonPath("$.items[0].due").value(2)).andExpect(jsonPath("$.items[0].expired").value(1)).andExpect(jsonPath("$.items[0].number").doesNotExist()).andExpect(header().string("Cache-Control","private, no-store"));mvc.perform(get(path+"/employees")).andExpect(status().isBadRequest());mvc.perform(get(path+"/employees?employeeIds=invalid")).andExpect(status().isBadRequest());when(service.list(any(),eq(store),eq(30),eq("all"),eq(50),eq(0),eq(employee))).thenReturn(new DocumentExpiryDtos.Page(store,"Asia/Singapore",LocalDate.of(2026,10,29),30,"all",0,0,0,50,0,List.of()));mvc.perform(get(path+"?employeeId="+employee)).andExpect(status().isOk());verify(service).list(any(),eq(store),eq(30),eq("all"),eq(50),eq(0),eq(employee));mvc.perform(get(path+"?employeeId=invalid")).andExpect(status().isBadRequest());}
}
